#include <stdio.h>
#include <stdlib.h>

void print_binary(int num) {
    unsigned int mask = 1 << (sizeof(int) * 8 - 1);
    while (mask > 0) {
        if (num & mask) {
            printf("1");
        } else {
            printf("0");
        }
        mask >>= 1;
    }
}

int main() {
    int num = 10; // first instruction
